let drawer;
export function showHelp(key) {
  const h = HELP[key]; if (!h) return;
  if (!drawer) { drawer = el('aside', { class: 'helpdrawer' }); document.body.append(drawer); }
  const row = (lab, txt) => txt ? el('div', { class: 'hrow' }, el('b', {}, lab), el('p', {}, txt)) : null;
  drawer.innerHTML = '';
  drawer.append(...[
    el('div', { class: 'hhead' }, el('h3', {}, h.t), el('button', { class: 'x', onclick: () => drawer.classList.remove('open') }, '×')),
    row('What it does', h.what), row('Why use it', h.why), row('When', h.when), row('How to adjust', h.how),
    row('Too high', h.hi), row('Too low', h.lo), row('Good starting point', h.start),
  ].filter(Boolean));
  drawer.classList.add('open');
}
export function helpBtn(key) {
  return el('button', { class: 'help', type: 'button', title: 'What is this?', onclick: e => { e.preventDefault(); e.stopPropagation(); showHelp(key); } }, '?');
}

